// Normaliza o que a LP manda para o formato da tabela `inscritos`.
//
// TROQUE AQUI A CADA TURMA NOVA. Carimbar a edição na origem é o ponto central da
// migração: hoje "de qual edição é este inscrito" é deduzido depois, por janela de
// data e casamento de UTM, e é daí que vieram os erros históricos (respostas com UTM
// genérica que não caíam em edição nenhuma, campanha renomeada sumindo do painel).
const EDICAO = 'webinar-31-08';

// Acha um campo ignorando caixa, espaço, hífen e underline: a LP já mandou
// `utm_source`, `utmSource` e `UTM Source` em momentos diferentes.
const pega = (obj, ...nomes) => {
  const limpa = (s) => String(s).toLowerCase().replace(/[\s_-]/g, '');
  for (const nome of nomes) {
    for (const chave of Object.keys(obj)) {
      if (limpa(chave) !== limpa(nome)) continue;
      const v = obj[chave];
      if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
    }
  }
  return null;
};

// Horário LOCAL do Brasil no formato que a coluna espera. `toLocaleString('sv-SE')`
// devolve "AAAA-MM-DD HH:MM:SS" — o formato sueco é o ISO sem o T.
const agoraBR = () => new Date().toLocaleString('sv-SE', { timeZone: 'America/Sao_Paulo' });

// A LP pode mandar a data em BR ("27/08/2026 16:40"). O Postgres leria isso como
// mês 27 e recusaria a linha inteira — ou, pior, aceitaria trocado. Converte antes.
const paraTimestamp = (v) => {
  if (!v) return agoraBR();
  const br = /^(\d{1,2})\/(\d{1,2})\/(\d{4})(?:[ T](\d{1,2}):(\d{2})(?::(\d{2}))?)?/.exec(v);
  if (br) {
    const [, d, m, a, hh = '00', mi = '00', ss = '00'] = br;
    return `${a}-${m.padStart(2, '0')}-${d.padStart(2, '0')} ${hh.padStart(2, '0')}:${mi}:${ss}`;
  }
  if (/^\d{4}-\d{2}-\d{2}/.test(v)) return v.replace('T', ' ').slice(0, 19);
  return agoraBR();
};

return items.map(({ json }) => {
  const email = pega(json, 'email', 'e-mail', 'mail');
  // Sem e-mail não há como deduplicar: melhor falhar aqui, visível no n8n, do que
  // gravar uma linha que nunca vai fechar com o painel.
  if (!email) throw new Error('Inscrição sem e-mail: ' + JSON.stringify(json).slice(0, 200));

  return {
    json: {
      edicao_id: EDICAO,
      email: email.toLowerCase(),
      nome: pega(json, 'nome', 'name', 'fullname'),
      telefone: pega(json, 'telefone', 'phone', 'whatsapp', 'celular'),
      membresia: pega(json, 'membresia', 'membros', 'tamanho da igreja'),
      cargo: pega(json, 'cargo', 'funcao', 'role'),
      utm_source: pega(json, 'utm_source'),
      utm_medium: pega(json, 'utm_medium'),
      utm_campaign: pega(json, 'utm_campaign'),
      utm_content: pega(json, 'utm_content'),
      utm_term: pega(json, 'utm_term'),
      url: pega(json, 'url', 'pagina', 'page_url', 'referrer'),
      inscrito_em: paraTimestamp(pega(json, 'data', 'inscrito_em', 'submitted_at', 'timestamp', 'createdat')),
      origem: 'n8n',
      payload: json
    }
  };
});
